import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = input_data[1]

    # DP table to store whether s[i..j] is a palindrome
    # dp[i][j] will be True if s[i..j] is a palindrome
    dp = [[False] * n for _ in range(n)]
    count = 0

    # Check for substrings of length 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if length == 2:
                if s[i] == s[j]:
                    dp[i][j] = True
                    count += 1
            else:
                if s[i] == s[j] and dp[i+1][j-1]:
                    dp[i][j] = True
                    count += 2
                else:
                    dp[i][j] = False

    print(count)

if __name__ == "__main__":
    solve()
